  "달력에는 업로드 일정과 정산 예정일만 표시됩니다. 브랜드가 희망 게시 기간을 23~26일처럼 범위로 적어 두면 그 기간 내내 이어서 표시되고, 콘텐츠를 올린 뒤에는 올린 날 하루로 바뀝니다. 정산일은 콘텐츠를 올린 달의 다음 달 말일이라, 업로드가 밀리면 정산일도 함께 밀립니다. 협업 기간과 금액 합계는 협업 내역 탭에서 볼 수 있습니다.": "カレンダーにはアップロード日程と精算予定日のみ表示されます。ブランドが希望掲載期間を23〜26日のように範囲で入力すると、その期間全体に表示され、コンテンツを投稿した後は投稿した日1日に変わります。精算日はコンテンツを投稿した月の翌月末日のため、アップロードが遅れると精算日も一緒に遅れます。コラボ期間と金額の合計はコラボ履歴タブで確認できます。",
