  "건 · 조회수": "件 · 再生数",
  "게시물 지표는 인플루언서 채널 연동에서 받아옵니다": "投稿の指標はインフルエンサーのチャネル連携から取得します",
  "업로드된 게시물 주소를 인플루언서의 메타 계정 최근 게시물과 맞춰 조회수·댓글·공유를 가져옵니다. 공유 수는 인스타그램 인사이트 값이라, 인플루언서가 채널을 다시 동기화한 뒤부터 채워집니다. 인플루언서가 직접 적은 숫자는 성과 근거로 쓰지 않기 때문에, 연동 전 게시물은 집계 전으로 남습니다. 메타는 최근 게시물만 돌려주므로 오래된 캠페인의 게시물도 집계에서 빠질 수 있습니다.": "アップロードされた投稿のURLをインフルエンサーのMetaアカウントの最近の投稿と照合し、再生数・コメント・シェアを取得します。シェア数はInstagramインサイトの値のため、インフルエンサーがチャネルを再同期した後から反映されます。インフルエンサーが自分で入力した数字は成果の根拠として使わないため、連携前の投稿は集計前のままになります。Metaは最近の投稿のみ返すため、古いキャンペーンの投稿は集計から外れることがあります。",
