  "게시물 그대로 부스팅은 가능합니다. 새 광고 소재로 편집하려면 인플루언서에게 클린본을 요청해 주세요.": "投稿のままブーストすることは可能です。新しい広告素材として編集するには、インフルエンサーにクリーン版をリクエストしてください。",
