  "달력에는 인플루언서의 업로드 일정만 표시됩니다. 등록할 때 희망 게시 기간을 23~26일처럼 범위로 적어 두면 그 기간 내내 이어서 표시되고, 콘텐츠가 올라간 뒤에는 올라간 날 하루로 바뀝니다. 기간을 적지 않은 협업은 캠페인 종료일에 놓이고, 담당자가 업로드 마감을 확정하면 그 날짜로 옮겨집니다. 협업 기간과 금액 합계는 협업 내역, 회차별 지급액은 정산금 탭에서 볼 수 있습니다.": "カレンダーにはインフルエンサーのアップロード日程のみ表示されます。登録時に希望掲載期間を23〜26日のように範囲で入力すると、その期間全体に表示され、コンテンツが投稿された後は投稿された日1日に変わります。期間を入力しなかったコラボはキャンペーン終了日に配置され、担当者がアップロード締切を確定するとその日付に移ります。コラボ期間と金額の合計はコラボ履歴、回ごとの支払額は精算金タブで確認できます。",
  "⬆️ 업로드 예정": "⬆️ アップロード予定",
