  "연동하기를 누른 브라우저(또는 앱)와 다른 곳에서 동의가 끝나 연동하지 않았어요. 연동하기를 누른 곳에서 다시 시도해 주세요.": "「連携する」を押したブラウザ(またはアプリ)とは別の場所で同意が完了したため、連携されませんでした。「連携する」を押した場所でもう一度お試しください。",
  "연동에 실패했어요. 다시 시도해 주세요.": "連携に失敗しました。もう一度お試しください。",
  "계정 연동은 로그인 후에 할 수 있어요.": "アカウント連携はログイン後に行えます。",
  "연동을 시작하지 못했습니다.": "連携を開始できませんでした。",
  "최신 정보를 불러왔어요. 릴스 조회수가 비어 있으면 계정을 다시 연동해 조회수 권한을 허용해 주세요.": "最新情報を読み込みました。リール再生数が空の場合は、アカウントを再連携して再生数の権限を許可してください。",
  "최신 팔로워·릴스 정보를 불러왔어요.": "最新のフォロワー・リール情報を読み込みました。",
  "인스타그램 계정 연동을 해제할까요? 지금까지 확인된 팔로워·조회수는 그대로 남지만, 해제 후에는 자동으로 갱신되지 않습니다. 언제든 다시 연동할 수 있어요.": "Instagramアカウントの連携を解除しますか?これまでに確認されたフォロワー・再生数はそのまま残りますが、解除後は自動で更新されません。いつでも再連携できます。",
  "인스타그램 연동이 해제되었습니다. 필요하면 언제든 다시 연동할 수 있어요.": "Instagramの連携を解除しました。必要であればいつでも再連携できます。",
  "이름을 입력해 주세요.": "名前を入力してください。",
  "담당자/브랜드명을 입력해 주세요.": "担当者名/ブランド名を入力してください。",
  "연락처를 입력해 주세요.": "連絡先を入力してください。",
  "인스타그램 계정을 연동해 주세요. 연동한 계정의 정보가 브랜드에게 전달됩니다.": "Instagramアカウントを連携してください。連携したアカウントの情報がブランドに伝わります。",
  "게시물 단가와 숏폼 단가를 모두 입력해 주세요.": "投稿単価とショート動画単価の両方を入力してください。",
  "카테고리를 최소 1개 골라 주세요. 캠페인은 분야로 인플루언서를 찾습니다.": "カテゴリを1つ以上選んでください。キャンペーンは分野でインフルエンサーを探します。",
