  "인스타그램 계정 연동": "Instagramアカウント連携",
  "유튜브 · 틱톡 추가 가능 (선택사항)": "YouTube · TikTokの追加も可能(任意)",
  "인스타그램": "Instagram",
  "연동 계정에서 자동 확인": "連携アカウントで自動確認",
  "연동된 계정": "連携済みアカウント",
