  "네이버 블로그 (선택사항)": "NAVERブログ(任意)",
  "인스타그램은 연동된 계정에서 정보를 확인합니다. 유튜브나 틱톡 등 추가 채널이 있다면 선택사항으로 입력하세요.": "Instagramは連携済みアカウントから情報を確認します。YouTubeやTikTokなど追加のチャネルがあれば任意で入力してください。",
  "인스타그램 연동으로 채널 정보가 연동됩니다. 유튜브나 틱톡은 필요 시 선택사항으로 추가 입력해 주세요.": "Instagram連携でチャネル情報が連携されます。YouTubeやTikTokは必要に応じて任意で追加入力してください。",
  "광고 단가": "広告単価",
  "게시물 단가": "投稿単価",
  "숏폼 단가": "ショート動画単価",
  "내 카테고리": "マイカテゴリ",
  "최소 1개는 골라 주세요. 여러 개 고를 수 있고, 목록에 없는 분야는 아래에서 직접 추가하세요.": "1つ以上選んでください。複数選択でき、一覧にない分野は下で直接追加できます。",
  "직접 추가 (예: 홈카페)": "直接追加(例: おうちカフェ)",
  "카테고리를 최소 1개 골라 주세요.": "カテゴリを1つ以上選んでください。",
  "담당자 이름 / 브랜드명": "担当者名 / ブランド名",
  "브랜드명 또는 담당자": "ブランド名または担当者",
  "브랜드 홈페이지": "ブランドのホームページ",
