  "뷰티, 패션, 푸드 등": "ビューティー、ファッション、フードなど",
  "추가 메모": "追加メモ",
  "캠페인 상세, 요청 사항 등": "キャンペーンの詳細、リクエストなど",
  "접수 중...": "受付中...",
  "수정 저장하기": "変更を保存する",
  "지원하기": "応募する",
  "수정 취소": "編集をキャンセル",
  "본인 인스타그램으로 로그인해 연동": "自分のInstagramでログインして連携",
  "연동하면 팔로워·팔로잉 수와 최근 릴스 평균 조회수를 픽스폴리오가 직접 확인해 보관합니다. 브랜드는 직접 적은 숫자보다 확인된 숫자를 신뢰하기 때문에 매칭 확률이 올라갑니다. 게시물 작성이나 DM 발송 권한은 사용하지 않습니다.": "連携すると、フォロワー・フォロー数と最近のリールの平均再生数をPICKSfolioが直接確認して保管します。ブランドは自己申告の数字より確認済みの数字を信頼するため、マッチングの確率が上がります。投稿の作成やDM送信の権限は使用しません。",
  "연동 창으로 이동 중...": "連携画面に移動中...",
  "인스타그램 계정 연동하기": "Instagramアカウントを連携する",
  "연동한 계정": "連携したアカウント",
  "· 다시 연동이 필요해요": "· 再連携が必要です",
  "인스타그램 동의 기간이 끝났습니다. 계정과 등록 정보는 그대로 있으니 다시 연동만 해 주시면 팔로워·릴스 조회수가 최신으로 채워집니다.": "Instagramの同意期間が終了しました。アカウントと登録情報はそのまま残っているので、再連携するだけでフォロワー・リール再生数が最新の状態に更新されます。",
  "다시 연동하기": "再連携する",
  "해제하는 중...": "解除中...",
  "연동 해제하기": "連携を解除する",
  "인스타그램 연동 완료": "Instagram連携完了",
  "메타에서 확인된 지표를 보관 중입니다.": "Metaで確認された指標を保管しています。",
  "연동됨 · 지표를 아직 받지 못했습니다.": "連携済み · 指標はまだ取得できていません。",
  "불러오는 중": "読み込み中",
  "새로 불러오기": "再読み込み",
  "릴스 평균 조회": "リール平均再生数",
  "릴스 조회수를 아직 받지 못했습니다. \"새로 불러오기\"를 눌러도 비어 있으면 계정을 다시 연동해 조회수(인사이트) 권한을 허용해 주세요. 팔로워 수는 정상적으로 확인되었습니다.": "リール再生数をまだ取得できていません。「再読み込み」を押しても空の場合は、アカウントを再連携して再生数(インサイト)の権限を許可してください。フォロワー数は正常に確認されました。",
  "다른 계정으로 바꾸려면 해제 후 다시 연동해 주세요.": "別のアカウントに切り替えるには、解除してから再連携してください。",
  "해제 중": "解除中",
  "연동 해제": "連携解除",
  "화면에서 색상 추출": "画面から色を抽出",
  "색상 선택": "色を選択",
  "개인 계정이나 비공개 계정은 연동할 수 없어요. 인스타그램 앱의 설정 → 계정 유형 및 도구에서 프로페셔널 계정(크리에이터 또는 비즈니스)으로 전환한 뒤 다시 연동해 주세요.": "個人アカウントや非公開アカウントは連携できません。Instagramアプリの設定 → アカウントの種類とツールでプロアカウント(クリエイターまたはビジネス)に切り替えてから、再度連携してください。",
  "개인정보 수집·이용에 동의해 주세요.": "個人情報の収集・利用に同意してください。",
  "미입력": "未入力",
  "인스타그램 다시 연동하기": "Instagramを再連携する",
  "인스타그램 연동하기": "Instagramを連携する",
  "개인정보처리방침": "プライバシーポリシー",
