  "선정 · 진행 준비": "選定 · 進行準備",
  "담당자가 조건을 정리하면 진행 단계가 열립니다.": "担当者が条件をまとめると進行段階が開きます。",
  "미선정": "選定外",
  "다른 캠페인에서 다시 만나요.": "また別のキャンペーンでお会いしましょう。",
  "오늘까지": "今日まで",
  "인스타그램 동의 화면에서 일부 권한이 꺼진 채로 진행돼 연동하지 않았어요. 다시 연동하면서 메시지·댓글 관리 등 모든 항목을 허용해 주세요.": "Instagramの同意画面で一部の権限がオフのまま進んだため、連携されませんでした。再連携の際は、メッセージ・コメントの管理などすべての項目を許可してください。",
  "인스타그램에서 허용 권한을 확인하지 못했습니다. 잠시 후 다시 연동해 주세요.": "Instagramで許可された権限を確認できませんでした。しばらくしてから再連携してください。",
  "인스타그램 연동에 실패했습니다. 다시 시도해 주세요.": "Instagramの連携に失敗しました。もう一度お試しください。",
