  "방금": "たった今",
  "인사이트는 프로 플랜 전용 기능입니다": "インサイトはプロプラン限定の機能です",
  "프로 플랜에 가입하면 모든 멤버십 혜택과 함께 인스타그램 인사이트를 볼 수 있어요. 가입은 PICKS Folio 웹사이트에서 할 수 있으며, 웹에서 가입하면 앱에서도 그대로 이용됩니다.": "プロプランに加入すると、すべてのメンバーシップ特典に加えてInstagramインサイトを確認できます。加入はPICKS Folioのウェブサイトで行え、ウェブで加入するとアプリでもそのまま利用できます。",
  "프로 플랜(월 18,700원 · 부가세 포함)을 구독하면 모든 멤버십 플랜 혜택과 함께 릴스 성과 · 팔로워 분석 · 벤치마킹을 볼 수 있어요.": "プロプラン(月18,700ウォン・税込)に登録すると、すべてのメンバーシッププランの特典に加えて、リールの成果・フォロワー分析・ベンチマーキングを確認できます。",
  "멤버십 플랜 보기": "メンバーシッププランを見る",
  "인스타그램 계정을 다시 연동해 주세요": "Instagramアカウントを再連携してください",
  "연동하면 팔로워 수와 릴스별 조회수·도달·저장수를 이 화면에서 볼 수 있어요.": "連携すると、フォロワー数とリールごとの再生数・リーチ・保存数をこの画面で確認できます。",
  "최근 7일 증감": "直近7日の増減",
  "수집 중": "収集中",
  "콘텐츠 성과": "コンテンツの成果",
  "팔로워 분석": "フォロワー分析",
  "벤치마킹": "ベンチマーキング",
  "업로드 전략": "投稿戦略",
  "릴스 성과": "リールの成果",
  "릴스별 조회수 · 도달 · 좋아요 · 댓글 · 저장 · 공유": "リールごとの再生数 · リーチ · いいね · コメント · 保存 · シェア",
  "일주일": "1週間",
  "2주": "2週間",
  "한 달": "1か月",
  "도달 · 저장 · 공유는 인스타그램 인사이트에서 받는 값입니다. 받지 못한 구간은 0 이 아니라 선이 끊겨 표시됩니다. 범례를 누르면 지표를 잠시 숨길 수 있어요.": "リーチ・保存・シェアはInstagramインサイトから取得する値です。取得できなかった区間は0ではなく線が途切れて表示されます。凡例を押すと指標を一時的に非表示にできます。",
  "팔로워 증감 추이": "フォロワー増減の推移",
  "하루 한 번 기록한 값 (한국 시간 기준)": "1日1回記録した値(韓国時間基準)",
  "가장 반응 좋은 릴스 TOP 5": "反応が最も良かったリールTOP5",
  "최근 릴스": "最近のリール",
  "저장수순": "保存数順",
  "인사이트 권한이 승인되기 전에 연동한 계정이라 도달·저장수가 비어 있습니다. 한 번만 다시 연동하면 이후로는 함께 불러옵니다.": "インサイト権限が承認される前に連携したアカウントのため、リーチ・保存数が空になっています。一度だけ再連携すれば、以降は一緒に読み込まれます。",
  "도달·저장수를 아직 받지 못했습니다. 계정을 다시 연동해 인사이트 접근을 허용하면 함께 보입니다.": "リーチ・保存数をまだ取得できていません。アカウントを再連携してインサイトへのアクセスを許可すると表示されます。",
  "아직 릴스가 없습니다": "まだリールがありません",
  "인스타그램에 릴스를 올리면 이 목록에 나타납니다.": "Instagramにリールを投稿すると、この一覧に表示されます。",
  "내 계정과 릴스 성과를 확인하세요": "自分のアカウントとリールの成果を確認しましょう",
  "이 기간에 올린 릴스가 없습니다": "この期間に投稿したリールはありません",
  "(이번 달)": "(今月)",
  "지난달 평균": "先月の平均",
  "릴스 수": "リール数",
  "좋아요 + 댓글": "いいね + コメント",
  "지난달에 올린 릴스가 없어 아직 비교할 값이 없습니다.": "先月に投稿したリールがないため、まだ比較できる値がありません。",
  "비교 불가": "比較不可",
  "지난달과 같음": "先月と同じ",
  "팔로워 수는 하루에 한 번 기록됩니다. 계정을 한 번 불러오면 첫 점이 생기고, 이틀치가 쌓이는 날부터 선으로 이어집니다.": "フォロワー数は1日1回記録されます。アカウントを一度読み込むと最初の点ができ、2日分たまった日から線でつながります。",
  "아직 하루치만 기록돼 있습니다. 이틀치가 쌓이는 날부터 선으로 이어집니다.": "まだ1日分しか記録されていません。2日分たまった日から線でつながります。",
  "늘어난 날 합계": "増えた日の合計",
  "줄어든 날 합계": "減った日の合計",
  "팔로워 구성": "フォロワー構成",
  "인스타그램이 알려주는 성별 · 연령대 · 국가 분포": "Instagramが提供する性別・年齢層・国の分布",
  "인스타그램이 아직 이 계정의 팔로워 구성을 집계하지 않았습니다. 이 값은 최대 48시간까지 늦게 반영되므로, 잠시 뒤 다시 열어 보면 채워져 있을 수 있어요.": "Instagramはまだこのアカウントのフォロワー構成を集計していません。この値は最大48時間遅れて反映されるため、しばらくしてから開くと表示されている場合があります。",
  "팔로워 구성을 불러오지 못했습니다. 계정을 다시 연동하면 대부분 해결됩니다.": "フォロワー構成を読み込めませんでした。アカウントを再連携するとほとんどの場合解決します。",
  "아직 받을 수 없는 값": "まだ取得できない値",
  "데이터 집계 중": "データ集計中",
  "성별 분포": "性別の分布",
  "연령대 분포": "年齢層の分布",
  "국가 분포": "国の分布",
  "비율은 인스타그램이 알려준 값의 합을 기준으로 계산합니다. 국가는 상위 45개까지만 내려오고 값이 최대 48시간 늦게 반영되므로, 팔로워 수와 정확히 맞지 않을 수 있습니다.": "割合はInstagramが提供した値の合計を基準に計算します。国は上位45か国までしか提供されず、値が最大48時間遅れて反映されるため、フォロワー数と正確に一致しない場合があります。",
  "나노": "ナノ",
  "1만 미만": "1万未満",
