  "동급 계정과 비교": "同規模アカウントとの比較",
  "비슷한 팔로워 규모의 인플루언서들과 내 채널 지표를 견줍니다": "似たフォロワー規模のインフルエンサーと自分のチャネル指標を比べます",
  "아직 견줄 값이 없습니다": "まだ比較できる値がありません",
  "채널 지표는 브랜드 매칭에 등록하면 만들어집니다. 등록하고 계정을 연동하면 이 탭에서 비슷한 규모 계정들과 견줄 수 있어요.": "チャネル指標はブランドマッチングに登録すると作成されます。登録してアカウントを連携すると、このタブで似た規模のアカウントと比較できます。",
  "비교 데이터를 불러오지 못했습니다. 잠시 후 다시 시도해 주세요.": "比較データを読み込めませんでした。しばらくしてから再度お試しください。",
  "비교 데이터 쌓이는 중": "比較データを蓄積中",
  "내 계정": "自分のアカウント",
  "동급 평균": "同規模の平均",
  "내 값": "自分の値",
  "편": "本",
  "비교는 등록된 인플루언서 모두에게 있는 채널 지표(브랜드에게 보이는 그 숫자)로 합니다. 저장률·공유율은 계정 주인 본인의 인사이트로만 받을 수 있는 값이라 평균이 존재하지 않아 비교 축에서 빼 뒀습니다 — 내 저장·공유는 콘텐츠 성과 탭에서 그대로 볼 수 있어요.": "比較は登録されたすべてのインフルエンサーが持つチャネル指標(ブランドに表示される数字)で行います。保存率・シェア率はアカウント所有者本人のインサイトでしか取得できない値のため平均が存在せず、比較軸から外しています — 自分の保存・シェアはコンテンツの成果タブでそのまま確認できます。",
  "정보형": "情報型",
  "저장이 유난히 많았던 편 — 다시 보려고 담아 둔 콘텐츠": "保存が特に多かった投稿 — 見返すために保存されたコンテンツ",
  "소통형": "コミュニケーション型",
  "댓글이 유난히 많았던 편 — 말을 걸고 싶게 만든 콘텐츠": "コメントが特に多かった投稿 — 話しかけたくなるコンテンツ",
  "확산형": "拡散型",
  "공유가 유난히 많았던 편 — 남에게 보여 주고 싶은 콘텐츠": "シェアが特に多かった投稿 — 人に見せたくなるコンテンツ",
  "이른 아침": "早朝",
  "늦은 오후": "夕方",
  "언제 올린 릴스가 실제로 잘됐는지, 어떤 반응을 받는 계정인지": "いつ投稿したリールが実際に伸びたか、どんな反応を受けるアカウントか",
  "이 탭은 내가 올린 릴스를 읽습니다. 몇 편 쌓이면 어느 요일 · 시간대가 실제로 잘됐는지 보여 줍니다.": "このタブは自分が投稿したリールを読み取ります。数本たまると、どの曜日・時間帯が実際に伸びたかを表示します。",
  "팔로워 활동 시간이 아니라 내가 실제로 올린 릴스의 성과로 계산했습니다.": "フォロワーのアクティブ時間ではなく、自分が実際に投稿したリールの成果で計算しました。",
  "아직 두드러지는 요일 · 시간대가 없습니다": "まだ目立つ曜日・時間帯はありません",
  "요일별 성과": "曜日別の成果",
  "시간대별 성과": "時間帯別の成果",
  "막대는 그 칸에 올린 릴스의 평균 조회수이고, 막대 위 숫자는 그 칸의 릴스 편수입니다. 흐린 막대는 한 편뿐인 칸이라 아직 근거로 쓰기 어렵습니다. 점선은 전체 평균 조회수입니다.": "棒はその枠に投稿したリールの平均再生数で、棒の上の数字はその枠のリール本数です。薄い棒は1本しかない枠のため、まだ根拠としては使いにくいです。点線は全体の平均再生数です。",
  "콘텐츠 유형": "コンテンツタイプ",
  "릴스마다 어떤 반응이 가장 두드러졌는지로 나눕니다 — 저장 · 댓글 · 공유": "リールごとにどの反応が最も目立ったかで分けます — 保存 · コメント · シェア",
  "아직 유형을 나눌 수 없습니다": "まだタイプを分けられません",
  "저장 · 공유는 인스타그램 인사이트에서 받는 값입니다. 계정을 다시 연동해 그 값이 들어오면 이 자리가 채워집니다.": "保存・シェアはInstagramインサイトから取得する値です。アカウントを再連携してその値が入ると、ここが表示されます。",
  "평균 조회수": "平均再生数",
  "AI 콘텐츠 코칭": "AIコンテンツコーチング",
  "AI 콘텐츠 코칭 준비 중": "AIコンテンツコーチング準備中",
  "평균": "平均",
  "저장": "保存",
  "실시간 트렌드 보드": "リアルタイムトレンドボード",
  "네이버 데이터랩 쇼핑인사이트 분야별 인기검색어 TOP 5": "NAVERデータラボ ショッピングインサイト 分野別人気検索ワードTOP5",
  "트렌드 데이터가 아직 수집되지 않았습니다.": "トレンドデータはまだ収集されていません。",
  "매일 오후 2시 업데이트에 채워집니다.": "毎日午後2時の更新で反映されます。",
  "출처: 네이버 데이터랩 쇼핑인사이트": "出典: NAVERデータラボ ショッピングインサイト",
  "안녕하세요! 관심 가져주셔서 감사합니다 😊 아래 링크에서 더 많은 정보를 확인해보세요.": "こんにちは!興味を持っていただきありがとうございます😊 下のリンクから詳しい情報をご覧ください。",
