  "보낼 메시지를 입력하면 여기에 표시됩니다.": "送るメッセージを入力するとここに表示されます。",
  "DM 미리보기": "DMプレビュー",
  "링크 버튼은 카드 형태로 전송됩니다. 인스타그램 모바일 앱에서만 표시되고 웹(instagram.com) DM 화면에서는 보이지 않습니다.": "リンクボタンはカード形式で送信されます。Instagramのモバイルアプリでのみ表示され、ウェブ(instagram.com)のDM画面には表示されません。",
  "캐러셀 카드": "カルーセルカード",
  "장이 발송됩니다. 카드는 인스타그램 모바일 앱에서만 표시되고 웹(instagram.com) DM 화면에서는 보이지 않습니다.": "枚が送信されます。カードはInstagramのモバイルアプリでのみ表示され、ウェブ(instagram.com)のDM画面には表示されません。",
  "이미지를 넣지 못했습니다. 다시 시도해 주세요.": "画像を追加できませんでした。もう一度お試しください。",
  "올리는 중": "アップロード中",
  "이 게시물에서는 사진을 가져올 수 없어요. 파일로 올려 주세요.": "この投稿からは写真を取得できません。ファイルでアップロードしてください。",
  "피드에서 가져오는 중": "フィードから取得中",
  "이미지 카드를 좌우로 넘겨보는 캐러셀 메시지예요. 카드는 최대": "画像カードを左右にスワイプして見るカルーセルメッセージです。カードは最大",
  "장까지 추가할 수 있고, 왼쪽 카드부터 순서대로 도착합니다. 이미지는 정사각형(1:1)을 권장하며": "枚まで追加でき、左のカードから順に届きます。画像は正方形(1:1)を推奨し、",
  "MB 이하 JPG·PNG·WEBP 를 넣을 수 있어요.": "MB以下のJPG・PNG・WEBPを追加できます。",
