  "캐러셀은 카드 한 통으로 발송됩니다. 인스타그램이 메시지 한 통에 텍스트와 카드를 함께 담지 못하기 때문에, 인사말처럼 전하고 싶은 문구는 카드의 제목·설명에 적어 주세요.": "カルーセルはカード1通として送信されます。Instagramは1通のメッセージにテキストとカードを一緒に入れられないため、あいさつなど伝えたい文言はカードのタイトル・説明に入力してください。",
  "(선택)": "(任意)",
  "설정 완료": "設定完了",
