  "연동이 해제되었습니다.": "連携を解除しました。",
  "저장했어요. 다만 자동 발송 스위치가 꺼져 있어 새 댓글에는 아직 DM이 나가지 않습니다. 발송하려면 위의 자동 발송을 켜주세요.": "保存しました。ただし自動送信スイッチがオフのため、新しいコメントにはまだDMが送信されません。送信するには上の自動送信をオンにしてください。",
