  "DM 창을 처음 여는 사람에게 추천 질문을 최대 4개 보여줍니다. 누르면 미리 정해 둔 답변이 바로 발송돼요.": "DM画面を初めて開いた人に、おすすめの質問を最大4つ表示します。押すとあらかじめ決めた回答がすぐに送信されます。",
