  "예) 💜 브랜드 소개": "例)💜 ブランド紹介",
  "이 질문을 누르면 보낼 답변을 적어주세요.": "この質問を押したときに送る回答を入力してください。",
  "질문 추가 (": "質問を追加(",
  "인스타그램에 등록하지 못했어요:": "Instagramに登録できませんでした:",
  "에 인스타그램에 등록했어요.": "にInstagramに登録しました。",
  "질문 버튼은": "質問ボタンは",
  "인스타그램 앱": "Instagramアプリ",
  "의 DM 화면에서만 보입니다(웹 instagram.com 은 이 기능을 지원하지 않아요). 또 대화를 한 번도 하지 않은 상대의 첫 화면에만 표시됩니다.": "のDM画面でのみ表示されます(ウェブのinstagram.comはこの機能に対応していません)。また、一度も会話したことのない相手の最初の画面にのみ表示されます。",
  "버튼이 놓이는 자리(가운데 정렬 · 오른쪽 정렬)와 색은": "ボタンの配置(中央揃え・右揃え)と色は",
  "인스타그램 앱이 정합니다": "Instagramアプリが決めます",
  ". 앱 버전과 다크 모드에 따라 달라서 우리 설정으로는 바꿀 수 없어요. 우리가 보내는 것은 질문 문구와 눌렀을 때 나갈 답변뿐입니다 — 문구 앞에 이모지를 하나 붙이고 짧게 쓰면 어느 배치에서도 잘 읽힙니다.": "。アプリのバージョンやダークモードによって変わるため、こちらの設定では変更できません。こちらから送るのは質問の文言と押したときの回答だけです — 文言の前に絵文字を1つ付けて短く書くと、どの配置でも読みやすくなります。",
  "인스타그램 계정을 연동하면 질문 버튼이 DM 창에 표시됩니다.": "Instagramアカウントを連携すると、質問ボタンがDM画面に表示されます。",
  "자동 발송 스위치가 꺼져 있어요. 스위치를 끄면 답변이 나가지 않기 때문에, 질문 버튼도 DM 창에서 함께 내려갑니다. 다시 켜면 자동으로 올라갑니다.": "自動送信スイッチがオフになっています。スイッチをオフにすると回答が送信されないため、質問ボタンもDM画面から一緒に取り下げられます。再度オンにすると自動で表示されます。",
  "처리하지 못했습니다.": "処理できませんでした。",
  "없음": "なし",
  "상품": "商品",
  "인사말을 켜 두셨어요. 보낼 인사말 문구를 입력해 주세요.": "あいさつ文がオンになっています。送るあいさつ文を入力してください。",
  "DM 자동 응답을 저장했어요.": "DM自動応答を保存しました。",
  "DM 자동 응답": "DM自動応答",
  "댓글과 무관하게, DM 을 받은 것 자체를 트리거로 씁니다. 처음 말을 걸어온 사람에게 인사말을 보내고, 메시지에 등록해 둔 단어가 있으면 그에 맞는 답장을 보냅니다.": "コメントとは関係なく、DMを受け取ったこと自体をトリガーにします。初めて話しかけてきた人にあいさつ文を送り、メッセージに登録した単語があればそれに合う返信を送ります。",
  "첫 인사말": "最初のあいさつ文",
  "예) 안녕하세요! 문의 주셔서 감사합니다 😊 궁금한 점을 남겨주시면 순서대로 답변드릴게요.": "例)こんにちは!お問い合わせありがとうございます😊 ご質問を残していただければ順番にお答えします。",
  "키워드 자동 답장": "キーワード自動返信",
  "받은 DM 에 특정 단어가 있을 때 보낼 답장을 만들어보세요": "受け取ったDMに特定の単語があるときに送る返信を作りましょう",
  "답장 삭제": "返信を削除",
  "키워드를 쉼표로 구분해 입력 (예: 가격, 얼마, 비용)": "キーワードをカンマで区切って入力(例: 価格, いくら, 費用)",
  "이 키워드가 들어오면 보낼 답장을 적어주세요.": "このキーワードが届いたときに送る返信を入力してください。",
  "답장 추가": "返信を追加",
  "받은 DM 에 답장하는 것은 인스타그램이 허용하는 범위입니다(상대가 먼저 말을 걸었으므로 24시간 동안 자유롭게 답장할 수 있어요). 키워드는 문장 안에 포함되면 걸립니다 — \"가격\"을 등록하면 \"가격 얼마예요?\"에도 답장이 나갑니다.": "受け取ったDMへの返信はInstagramが許可している範囲です(相手から先に話しかけてきたため、24時間は自由に返信できます)。キーワードは文中に含まれていれば反応します —「価格」を登録すると「価格はいくらですか?」にも返信されます。",
  "자동 발송 스위치가 꺼져 있어 지금은 답장이 나가지 않습니다. 설정은 저장돼요.": "自動送信スイッチがオフのため、今は返信が送信されません。設定は保存されます。",
