  "연동하면 Meta Marketing API로 실제 광고를 만들고 조회합니다": "連携すると、Meta Marketing APIで実際の広告を作成・照会します",
  "집행하기를 누르면 선택한 광고 계정에 캠페인 · 광고 세트 · 소재 · 광고가 만들어지고, 광고 상태와 지표는 Meta에서 바로 읽어 옵니다. 관리하는 페이스북 페이지 목록과 게시물 반응도 함께 불러옵니다.": "「配信する」を押すと、選択した広告アカウントにキャンペーン・広告セット・クリエイティブ・広告が作成され、広告のステータスと指標はMetaから直接読み込みます。管理しているFacebookページの一覧と投稿の反応も一緒に読み込みます。",
