  "선택됨": "選択済み",
  "Meta로 이동 중...": "Metaに移動中...",
  "연동 해제는 픽스폴리오에 남은 연동 기록을 지웁니다. Meta 쪽 앱 권한까지 회수하려면 Facebook 설정 &gt; 비즈니스 통합에서 앱을 삭제해 주세요.": "連携を解除するとPICKSfolioに残っている連携記録が削除されます。Meta側のアプリ権限まで取り消すには、Facebookの設定 &gt; ビジネス統合でアプリを削除してください。",
  "아직 Meta 계정이 연동되지 않았습니다": "まだMetaアカウントが連携されていません",
  "Meta 계정을 연동하면 광고 계정을 고르고, 캠페인 이력에서 고른 콘텐츠를 픽스폴리오 안에서 바로 광고로 돌릴 수 있습니다.": "Metaアカウントを連携すると広告アカウントを選べ、キャンペーン履歴で選んだコンテンツをPICKSfolio内ですぐに広告として配信できます。",
  "Meta 계정 연동하기": "Metaアカウントを連携する",
