  "testuser, 더미 제안 등 운영과 무관한 데이터를 숨기거나 표시합니다.": "testuser、ダミー提案など運営と関係のないデータを非表示または表示します。",
  "광고주": "広告主",
  "금액 / 기간": "金額 / 期間",
  "해당 상태의 제안이 없습니다.": "このステータスの提案はありません。",
