  "수익 배분:": "収益配分:",
  "캠페인 승인 · 공개 모집형 캠페인 심사": "キャンペーン承認 · 公開募集型キャンペーンの審査",
  "광고주가 등록한 공개 모집 캠페인을 노출 전에 승인/거절합니다. 한 줄에 브랜드·단가·예산·모집·기간·담당자가 모두 보이며, 설명과 지원 조건은 '상세'를 눌러 확인합니다.": "広告主が登録した公開募集キャンペーンを、掲載前に承認/却下します。1行にブランド・単価・予算・募集・期間・担当者がすべて表示され、説明と応募条件は「詳細」を押して確認します。",
  "아직 데이터가 없습니다.": "まだデータがありません。",
  "관리자 인증이 완료되면 캠페인 승인 관리가 표시됩니다.": "管理者認証が完了すると、キャンペーン承認管理が表示されます。",
  "관리자 인증이 완료되면 인플루언서 리스트업이 표시됩니다.": "管理者認証が完了すると、インフルエンサーのリストアップが表示されます。",
  "캠페인 관리 · 전체 진행과 담당자 배정": "キャンペーン管理 · 全体の進行と担当者の割り当て",
  "모든 캠페인이 어느 단계에서 멈춰 있고 누가 맡고 있는지 한 표로 봅니다. 담당자를 바로 바꿀 수 있고, 아래 협업 콘솔에서는 조건 확정·제출물 검수·정산 예약을 처리합니다.": "すべてのキャンペーンがどの段階で止まっていて、誰が担当しているかを1つの表で確認します。担当者をすぐに変更でき、下のコラボコンソールでは条件確定・提出物の検収・精算の予約を処理します。",
  "선정 인플루언서 협업 관리": "選定インフルエンサーのコラボ管理",
  "관리자 인증이 완료되면 캠페인 관리가 표시됩니다.": "管理者認証が完了すると、キャンペーン管理が表示されます。",
  "인플루언서 DB · 카테고리 · 팔로워 · 인사이트": "インフルエンサーDB · カテゴリ · フォロワー · インサイト",
  "픽스폴리오에 등록된 인플루언서를 한 표로 정리해 둡니다. 인플루언서가 브랜드 매칭 등록에서 직접 고른 분야로 추린 뒤, 팔로워 많은 순과 인사이트 좋은 순으로 나란히 볼 수 있습니다. 인사이트는 조회율·반응률·최근 릴스 동향을 합친 점수로, 팔로워 규모와 무관하게 콘텐츠 성과만 봅니다.": "PICKSfolioに登録されたインフルエンサーを1つの表にまとめます。インフルエンサーがブランドマッチング登録で自ら選んだ分野で絞り込んだ後、フォロワーの多い順とインサイトの良い順で並べて見られます。インサイトは再生率・反応率・最近のリールの動向を合わせたスコアで、フォロワー規模に関係なくコンテンツの成果だけを見ます。",
  "관리자 인증이 완료되면 인플루언서 DB가 표시됩니다.": "管理者認証が完了すると、インフルエンサーDBが表示されます。",
  "브랜드 매칭 지원자 · 인플루언서 채널 검토": "ブランドマッチング応募者 · インフルエンサーのチャネル審査",
  "브랜드 매칭 받기에 지원한 인플루언서를 지원자가 직접 고른 분야별로, 그리고 팔로워 구간별로 확인합니다. 팔로워 많은 순과 인사이트(조회율·반응률·릴스 동향) 좋은 순으로 정렬을 바꿔 볼 수 있고, 연결된 Instagram Meta 계정에서 팔로워·팔로잉과 최근 릴스 성과를 갱신해 검토할 수 있습니다.": "ブランドマッチングに応募したインフルエンサーを、応募者が自ら選んだ分野別、そしてフォロワー帯別に確認します。フォロワーの多い順とインサイト(再生率・反応率・リールの動向)の良い順で並べ替えられ、連携されたInstagramのMetaアカウントからフォロワー・フォロー数と最近のリールの成果を更新して審査できます。",
  "관리자 인증이 완료되면 지원자 목록이 표시됩니다.": "管理者認証が完了すると、応募者一覧が表示されます。",
  "관리자 인증이 완료되면 인플루언서 데이터가 표시됩니다.": "管理者認証が完了すると、インフルエンサーのデータが表示されます。",
  "관리자 인증이 완료되면 담당자 목록이 표시됩니다.": "管理者認証が完了すると、担当者一覧が表示されます。",
  "정산·매출 · 세 수익원의 순수익": "精算・売上 · 3つの収益源の純利益",
  "멤버십 구독료, 캠페인 마진(브랜드 제시가 − 인플루언서 단가), AI 사용 순수익을 나눠 봅니다. 아래 정산 콘솔에서 인플루언서 지급 예약과 완료 처리를 합니다.": "メンバーシップ料金、キャンペーンのマージン(ブランド提示額 − インフルエンサー単価)、AI利用の純利益を分けて見ます。下の精算コンソールでインフルエンサーへの支払い予約と完了処理を行います。",
  "관리자 인증이 완료되면 정산 데이터가 표시됩니다.": "管理者認証が完了すると、精算データが表示されます。",
