  "영문 소문자, 숫자, 밑줄(_)로 바꿔 입력했습니다.": "英小文字、数字、アンダースコア(_)に変換して入力しました。",
  "인증번호가 일치하지 않거나 만료되었습니다.": "認証番号が一致しないか、有効期限が切れています。",
  "휴대폰 번호 인증을 완료해 주세요.": "携帯電話番号の認証を完了してください。",
  "회원가입이 완료되었습니다! 로그인해 주세요.": "会員登録が完了しました!ログインしてください。",
  "회원가입 중 오류가 발생했습니다.": "会員登録中にエラーが発生しました。",
