  "줄 왼쪽 화살표를 누르면 브랜드 픽 · 제안 단계와 마진 계산 근거를 볼 수 있습니다. 진행 단계는 지원자 수 → 리스트업 후보 → 브랜드가 진행 요청한 후보 → 담당자가 조건을 보낸 후보 → 수락한 후보 → 진행 중 협업 순입니다. 마진은 브랜드 제시가와 인플루언서 단가가 모두 입력된 수락 후보만 집계합니다.": "行の左の矢印を押すと、ブランドピック・提案段階とマージン計算の根拠を確認できます。進行段階は、応募者数 → リストアップ候補 → ブランドが進行を依頼した候補 → 担当者が条件を送った候補 → 承諾した候補 → 進行中のコラボの順です。マージンはブランド提示額とインフルエンサー単価が両方入力された承諾候補のみを集計します。",
