  "계정 @": "アカウント @",
  "정산금을 지급하셨습니까? 인플루언서 화면에도 정산완료로 표시됩니다.": "精算金を支払いましたか?インフルエンサーの画面にも精算完了と表示されます。",
  "픽스폴리오에 정산할 금액": "PICKSfolioに精算する金額",
  "아직 진행이 확정된 인플루언서가 없습니다": "まだ進行が確定したインフルエンサーはいません",
  "· 청구서 발행": "· 請求書発行",
  "정산완료": "精算完了",
  "입금 확인 대기": "入金確認待ち",
  "입금 확인 완료 · 인플루언서 지급은 픽스폴리오가 진행합니다.": "入金確認完了 · インフルエンサーへの支払いはPICKSfolioが行います。",
  "픽스폴리오에서 입금을 확인하면 이 칸이 '정산완료'로 바뀝니다.": "PICKSfolioで入金を確認すると、この欄が「精算完了」に変わります。",
  "광고비 조율 중": "広告費調整中",
  "명이 아직 포함되지 않았습니다.": "名がまだ含まれていません。",
  "등록할 때 적은 예산이 아니라 실제로 진행이 확정된 인플루언서들의 광고비 합계입니다. 명단에서 보신 광고비가 그대로 더해지고, 명단이 늘거나 줄면 이 금액도 따라 바뀝니다. 인플루언서 개별 지급과 원천징수(3.3%)는 입금 확인 후 픽스폴리오가 처리하고, 세금계산서도 그때 발행됩니다.": "登録時に入力した予算ではなく、実際に進行が確定したインフルエンサーの広告費の合計です。名簿で見た広告費がそのまま加算され、名簿が増減するとこの金額も変わります。インフルエンサーへの個別支払いと源泉徴収(3.3%)は入金確認後にPICKSfolioが処理し、税金計算書もその際に発行されます。",
  "일괄 정산 총액": "一括精算の総額",
  "건이 총액에 아직 포함되지 않았습니다.": "件が総額にまだ含まれていません。",
  "아직 정산 예정 내역이 없습니다": "まだ精算予定の履歴はありません",
  "정산은 담당자가 업로드를 확인한 뒤 예약됩니다.": "精算は担当者がアップロードを確認した後に予約されます。",
  "지급일은 콘텐츠를 올린 달의 다음 달 말일입니다.": "支払日はコンテンツを投稿した月の翌月末日です。",
  "정산 회차": "精算の回",
  "같은 지급일의 협업이 한 회차로 묶입니다. '정산완료'는 픽스폴리오가 입금을 확인한 회차입니다.": "同じ支払日のコラボが1回分にまとめられます。「精算完了」はPICKSfolioが入金を確認した回です。",
  "표시된 금액은 픽스폴리오로 입금하는 금액입니다": "表示されている金額はPICKSfolioに入金する金額です",
  ". 입금이 확인되면 회차가 '정산완료'로 바뀌고, 인플루언서 개별 지급과 원천징수(3.3%)는 그 뒤에 픽스폴리오가 처리합니다. 세금계산서는 입금 확인 후 발행됩니다. 지급일은 콘텐츠를 올린 달의 다음 달 말일입니다.": ". 入金が確認されるとその回が「精算完了」に変わり、インフルエンサーへの個別支払いと源泉徴収(3.3%)はその後PICKSfolioが処理します。税金計算書は入金確認後に発行されます。支払日はコンテンツを投稿した月の翌月末日です。",
  "내가 직접 제안해 성사된 협업입니다. 정산금은 픽스폴리오를 거치지 않고 인플루언서에게 바로 지급하며, 지급 후 '정산완료'를 눌러 주세요. 인플루언서가 먼저 확인해도 완료로 바뀝니다.": "自分で直接提案して成立したコラボです。精算金はPICKSfolioを通さずインフルエンサーに直接支払い、支払い後に「精算完了」を押してください。インフルエンサーが先に確認しても完了に変わります。",
  "기획안 작성": "企画書の作成",
  "브랜드가 진행사항에 올린 가이드 파일을 먼저 끝까지 읽고, 그 내용대로 이 캠페인의 기획안을": "ブランドが進行状況にアップロードしたガイドファイルをまず最後まで読み、その内容どおりにこのキャンペーンの企画書を",
  "작성해 주세요. 가이드에 있는 필수 표기와 필수 장면을 실제 장면 안에 넣어서 장면별로 써 주세요.": "作成してください。ガイドにある必須表記と必須シーンを実際のシーンの中に入れて、シーンごとに書いてください。",
  "피드백대로 기획안 수정": "フィードバックどおりに企画書を修正",
  "브랜드가 남긴 피드백을 하나도 빠뜨리지 말고 반영해서 기획안을 수정해 주세요. 지적받지 않은": "ブランドが残したフィードバックを1つも漏らさず反映して企画書を修正してください。指摘されていない",
  "장면은 그대로 두고, 어느 장면을 왜 고쳤는지 알려 주세요.": "シーンはそのままにして、どのシーンをなぜ直したかを教えてください。",
  "나레이션 없는 기획안": "ナレーションなしの企画書",
  "작성해 주세요. 나레이션(대사)은 넣지 말고 자막과 장면 설명만으로 써 주세요. 가이드의 필수": "作成してください。ナレーション(セリフ)は入れず、字幕とシーンの説明だけで書いてください。ガイドの必須",
  "표기와 필수 장면은 자막과 장면 안에 빠짐없이 넣어 주세요.": "表記と必須シーンは字幕とシーンの中に漏れなく入れてください。",
  "본문 작성": "本文の作成",
  "브랜드가 올린 가이드 파일을 읽고, 이 캠페인 게시물에 쓸 인스타그램 본문을 써 주세요. 첫 줄로": "ブランドがアップロードしたガイドファイルを読み、このキャンペーン投稿に使うInstagramの本文を書いてください。1行目で",
  "시선을 잡고, 가이드의 필수 문구와 해시태그, 계정 태그를 빠짐없이 넣어 주세요.": "目を引き、ガイドの必須文言とハッシュタグ、アカウントタグを漏れなく入れてください。",
  "피드백대로 본문 수정": "フィードバックどおりに本文を修正",
  "브랜드 피드백에 맞춰 인스타그램 본문을 수정해 주세요. 무엇을 고쳤는지도 알려 주세요.": "ブランドのフィードバックに合わせてInstagramの本文を修正してください。何を直したかも教えてください。",
  "가이드 필수사항 정리": "ガイドの必須事項を整理",
  "브랜드가 진행사항에 올린 가이드 파일을 읽고, 이 캠페인에서 반드시 지켜야 할 것과 하면 안 되는": "ブランドが進行状況にアップロードしたガイドファイルを読み、このキャンペーンで必ず守るべきことと、してはいけない",
