  "AI 어시스턴트는 AI 협업 멤버십(6,900원) 이상에서 이용할 수 있어요. 플랜을 업그레이드하면 바로 사용할 수 있습니다.": "AIアシスタントはAIコラボメンバーシップ(6,900ウォン)以上で利用できます。プランをアップグレードするとすぐに使えます。",
