  "장면 하나에 설명 · 자막 · 나레이션을 적고, 아래 + 로 다음 장면을 추가하세요. 자막과 나레이션은 없으면 비워 두셔도 됩니다. 브랜드는 장면마다 피드백을 답니다.": "1つのシーンに説明・字幕・ナレーションを書き、下の+で次のシーンを追加してください。字幕とナレーションはなければ空欄で構いません。ブランドはシーンごとにフィードバックを付けます。",
