  "인스타 본문 캡션": "Instagram本文のキャプション",
  "영상 아래에 들어갈 본문을 그대로 적어 주세요. 예) 요즘 아침마다 챙겨 먹는 것 🌿 · 하루 한 포로 간단하게 · 물 없이도 먹을 수 있어요 #광고 #브랜드명 #제품명": "動画の下に入る本文をそのまま書いてください。例)最近毎朝欠かさず飲んでいるもの🌿 · 1日1包で手軽に · 水なしでも飲めます #PR #ブランド名 #商品名",
  "해시태그와 광고 표기(#광고 · 유료광고 포함)까지 함께 적어 주세요. 브랜드가 이 글에도 피드백을 남깁니다.": "ハッシュタグと広告表記(#PR・有料広告を含む)まで一緒に書いてください。ブランドはこの文章にもフィードバックを残します。",
