  "인스타 본문 캡션 · 이 글이 영상 아래에 게시됩니다": "Instagram本文のキャプション · この文章が動画の下に投稿されます",
  "본문 캡션이 비어 있습니다. 아래 칸으로 본문도 함께 요청해 주세요 — 검토하지 않으면 업로드 당일에 처음 보게 됩니다.": "本文のキャプションが空です。下の欄から本文も一緒に依頼してください — 確認しないと、アップロード当日に初めて見ることになります。",
  "인플루언서가 초안 영상과 본문 캡션을 올리면 여기에 표시됩니다.": "インフルエンサーが初稿の動画と本文のキャプションをアップロードするとここに表示されます。",
