  "고쳤으면 하는 문장과 이유를 적어 주세요. (예: 첫 줄에 제품명이 들어가야 합니다 / #광고 표기를 맨 앞으로)": "直してほしい文章と理由を書いてください。(例: 1行目に商品名を入れてください / #PR表記を先頭に)",
  "본문 캡션이 먼저 올라왔습니다. 초안 영상이 올라오면 영상과 본문을 함께 검토할 수 있어요.": "本文のキャプションが先にアップロードされました。初稿の動画がアップロードされると、動画と本文を一緒に確認できます。",
  "본문 캡션은 저장됐습니다. 초안 영상을 올리면 브랜드가 영상과 본문을 함께 검토합니다.": "本文のキャプションは保存されました。初稿の動画をアップロードすると、ブランドが動画と本文を一緒に確認します。",
  "검토를 완료하면 이 영상과 본문 캡션이 그대로 게시됩니다. 두 가지를 모두 확인한 뒤 눌러 주세요.": "確認を完了すると、この動画と本文のキャプションがそのまま投稿されます。両方を確認してから押してください。",
  "영상 검토 완료": "動画の確認完了",
  "영상 검토 완료 · 담당자와 소통 후 업로드 일정을 정하세요": "動画の確認完了 · 担当者と相談してアップロード日程を決めてください",
  "검토를 마친 영상과 본문 캡션은 이대로 확정입니다. 언제 올릴지는 담당자와 이야기해 정한 뒤 게시해 주세요. 올린 뒤 업로드 단계에 게시물 링크와 광고 파트너십 코드를 남기면 끝입니다.": "確認を終えた動画と本文のキャプションはこのまま確定です。いつ投稿するかは担当者と話して決めてから投稿してください。投稿後、アップロード段階で投稿のリンクと広告パートナーシップコードを残せば完了です。",
  "검토 완료된 본문 캡션 · 이대로 붙여넣어 주세요": "確認済みの本文キャプション · このまま貼り付けてください",
