  "픽스폴리오가 입금을 확인했습니다. 인플루언서 지급과 원천징수는 픽스폴리오가 진행합니다.": "PICKSfolioが入金を確認しました。インフルエンサーへの支払いと源泉徴収はPICKSfolioが行います。",
  "정산은 픽스폴리오에 한 번 보내면 됩니다. 캠페인 정산 탭에서 보낼 금액을 확인해 주세요.": "精算はPICKSfolioに一度送るだけです。キャンペーンの精算タブで送る金額を確認してください。",
