  "예금주가 신분증의 이름과 다르면 은행에서 반송됩니다. 제출한 서류는 담당자만 열어 볼 수 있고 브랜드에게는 제출 여부만 표시됩니다.": "口座名義が身分証の名前と異なると銀行から返送されます。提出した書類は担当者のみ閲覧でき、ブランドには提出の有無だけが表示されます。",
