  "저장하면 인플루언서 정산금 화면의 지급 예정일과 협업 현황 캘린더에 그대로 올라갑니다.": "保存すると、インフルエンサーの精算金画面の支払予定日とコラボ状況カレンダーにそのまま表示されます。",
  "브랜드 입금 확인 전입니다": "ブランドの入金確認前です",
