  "게시물 등록됨 · 브랜드 확인 대기": "投稿登録済み · ブランドの確認待ち",
  "브랜드 검토 완료 · 담당자와 소통 후 업로드 일정을 정하세요": "ブランドの確認完了 · 担当者と相談してアップロード日程を決めてください",
  "검토를 마친 초안 영상과 본문 캡션을 그대로 올리시면 됩니다. 올리는 날짜는 담당자와 맞춰 주세요. 올린 뒤 아래에 게시물 링크와 광고 파트너십 코드, 클린본 영상을 남겨 주세요.": "確認を終えた初稿の動画と本文のキャプションをそのまま投稿してください。投稿日は担当者と合わせてください。投稿後、下に投稿のリンクと広告パートナーシップコード、クリーン版の動画を残してください。",
