  "캠페인이 수정되었습니다.": "キャンペーンを変更しました。",
  "캠페인이 등록되었습니다. 담당자가 조건에 맞는 인플루언서를 찾아 리스트업해 드립니다.": "キャンペーンを登録しました。担当者が条件に合うインフルエンサーを探してリストアップします。",
  "캠페인이 등록되었습니다. 승인 후 캠페인 협업 목록에 올라가고, 지원자가 모이면 그 중에서 고르실 수 있습니다.": "キャンペーンを登録しました。承認後にキャンペーンコラボの一覧に掲載され、応募者が集まったらその中から選べます。",
  "제품 소개는 왜 필요할까요?": "商品紹介はなぜ必要ですか?",
  "인플루언서가 지원 여부를 정할 때 가장 먼저 읽는 내용입니다. 제품의 특징과 꼭 강조하고 싶은 점을 두세 줄로 적어 주세요.": "インフルエンサーが応募するかどうかを決めるときに最初に読む内容です。商品の特徴とぜひ強調したい点を2〜3行で書いてください。",
  "예산은 어떻게 정할까요?": "予算はどう決めればいいですか?",
  "커머스는 무엇이 다를까요?": "コマースは何が違いますか?",
  "제품 협찬형은 무엇이 다를까요?": "商品協賛型は何が違いますか?",
  "캠페인 협업 목록에 올라가고, 판매를 함께할 인플루언서가 직접 지원합니다. 광고비 대신 판매 수수료로 정산하며, 콘텐츠 검수와 수수료 정산 단계가 있습니다.": "キャンペーンコラボの一覧に掲載され、一緒に販売するインフルエンサーが直接応募します。広告費の代わりに販売手数料で精算し、コンテンツの検収と手数料精算の段階があります。",
  "캠페인 협업 목록에 올라가고, 인플루언서가 직접 지원합니다. 광고비 없이 제품만 제공하므로 구성안·콘텐츠 검수 단계가 없고, 가이드를 전달한 뒤 업로드를 확인하는 흐름으로 진행됩니다.": "キャンペーンコラボの一覧に掲載され、インフルエンサーが直接応募します。広告費なしで商品のみ提供するため構成案・コンテンツの検収段階はなく、ガイドを伝えた後にアップロードを確認する流れで進みます。",
  "캠페인 수정": "キャンペーンを編集",
