  "진행 방법": "進め方",
  "지원자를 수락하면 픽스폴리오 담당자가 배정되어 브랜드와 인플루언서 양쪽에 직접 연락해 조건과 일정을 정리합니다. 화면에서 단계를 하나씩 눌러 진행하지 않아도 됩니다.": "応募者を承諾するとPICKSfolioの担当者が割り当てられ、ブランドとインフルエンサーの両方に直接連絡して条件とスケジュールをまとめます。画面で段階を1つずつ押して進める必要はありません。",
