  "인플루언서에게 \"픽스폴리오 채널로 메시지를 보내 달라\"는 알림톡이 갑니다. 인플루언서가 채팅방에 답을 남기면 카카오톡 채널 관리자센터의 1:1 채팅에서 이어서 대화하세요.": "インフルエンサーに「PICKSfolioのチャネルにメッセージを送ってください」というアラートトークが届きます。インフルエンサーがチャットルームに返信したら、カカオトークチャネル管理センターの1:1チャットで会話を続けてください。",
  "이 인플루언서는 카카오 계정 연락처가 없어 연락 요청을 보낼 수 없습니다.": "このインフルエンサーはカカオアカウントの連絡先がないため、連絡リクエストを送れません。",
