  "접근 가능한 원화(KRW) 광고 계정이 필요합니다. Meta 광고 계정 통화를 확인해 주세요.": "アクセスできるウォン(KRW)建ての広告アカウントが必要です。Meta広告アカウントの通貨を確認してください。",
