  "휴대폰 번호를 정확히 입력해 주세요.": "携帯電話番号を正確に入力してください。",
  "이 브랜드": "このブランド",
  "수락하기": "承諾する",
  "광고비 지급 캠페인을 등록하고, 담당자가 추천한 인플루언서를 선정해 기획안 · 초안 영상 · 업로드까지 진행하세요.": "広告費を支払うキャンペーンを登録し、担当者がおすすめしたインフルエンサーを選定して、企画書・初稿の動画・アップロードまで進めましょう。",
  "🏬 어필리에이트": "🏬 アフィリエイト",
