  "판매 수수료(어필리에이트)": "販売手数料(アフィリエイト)",
  "매달 확정된 판매 수수료를 모아 정산합니다. 원천징수 3.3%를 뗀 금액이 지급 계좌로 들어오고, 지급이 끝나면 자동으로 정산완료로 바뀝니다.": "毎月確定した販売手数料をまとめて精算します。源泉徴収3.3%を差し引いた金額が支払口座に入金され、支払いが終わると自動で精算完了に変わります。",
