  "지급 대기 중인 신청 · 은행, 계좌번호 전체, 예금주, 금액(인플루언서는 실지급액)": "支払い待ちの申請 · 銀行、口座番号(全桁)、口座名義、金額(インフルエンサーは実支給額)",
