  "인플루언서 반려": "インフルエンサーが辞退",
  "문자": "SMS",
  "링크를 다시 열까요? 인플루언서의 전용 판매 링크로 다시 주문을 받을 수 있습니다.": "リンクを再び開きますか?インフルエンサーの専用販売リンクから再び注文を受けられます。",
  "링크를 잠시 닫을까요? 닫는 동안 이 인플루언서 링크로는 주문할 수 없습니다.": "リンクを一時的に閉じますか?閉じている間は、このインフルエンサーのリンクから注文できません。",
  "어필리에이트 협업 진행": "アフィリエイトのコラボ進行",
  "브랜드가 선정한 협업이 선정 즉시 여기에 올라옵니다. 브랜드 · 인플루언서 연락처를 바로 눌러 전화 · 문자로 연락하고, 배송 · 업로드 일정을 중간에서 조율해 주세요. 문제가 있으면 링크를 잠시 닫을 수 있습니다.": "ブランドが選定したコラボは、選定と同時にここに表示されます。ブランド・インフルエンサーの連絡先を押してすぐに電話・SMSで連絡し、配送・アップロードの日程を間に入って調整してください。問題があれば、リンクを一時的に閉じることができます。",
