  "등록된 연락처가 없습니다. 배송정보를 입력하면 배송지 연락처가 표시됩니다 — 그 전에는 인스타그램 DM으로 연락해 주세요.": "登録された連絡先はありません。配送情報を入力すると配送先の連絡先が表示されます — それまではInstagramのDMで連絡してください。",
