  "수수료율을 바꿀까요? 이미 생긴 주문에는 적용되지 않고, 다음 주문부터 적용됩니다.": "手数料率を変更しますか?すでに発生した注文には適用されず、次の注文から適用されます。",
  "수수료율 설정": "手数料率の設定",
  "브랜드 정산액 = 결제 금액(상품 + 배송비) − 인플루언서 수수료 − 플랫폼 수수료(상품 금액 기준) − PG 수수료(결제 금액 기준, 배송비 포함). 반품 환불(상품 금액만 환불)된 주문은 남은 배송비에서 PG 수수료만 빼고 브랜드에 정산됩니다. 주문 생성 시점 값이 주문에 고정됩니다.": "ブランドの精算額 = 決済金額(商品 + 送料)− インフルエンサー手数料 − プラットフォーム手数料(商品金額基準)− PG手数料(決済金額基準、送料込み)。返品返金(商品金額のみ返金)された注文は、残りの送料からPG手数料のみを差し引いてブランドに精算されます。注文作成時点の値が注文に固定されます。",
  "플랫폼(픽스폴리오) 수수료": "プラットフォーム(PICKSfolio)手数料",
