  "예전 아이디·비밀번호로 가입한 인플루언서가 카카오로 다시 가입하면, 링크 만들기 화면에서 쓰던 유저네임을 그대로 이어받습니다. 카카오 휴대폰 번호가 예전 번호와 같으면 바로 옮겨지고, 다르면 본인 확인 후 여기서 발급한 이전 코드(14일 유효)를 전달해 주세요.": "以前のID・パスワードで登録したインフルエンサーがカカオで再登録すると、リンク作成画面で使っていたユーザーネームをそのまま引き継ぎます。カカオの携帯電話番号が以前の番号と同じならすぐに移行され、異なる場合は本人確認後にここで発行した以前のコード(14日間有効)を伝えてください。",
