  "구매 페이지에서 DESCRIPTION · SIZE GUIDE · DELIVERY GUIDE 칸으로 나뉘어 보입니다. 세 칸 모두 필수이며, 칸마다 글을 적거나 이미지(사이즈표 · 배송 안내 이미지 등)를 올리면 됩니다. 인플루언서도 판매 신청 전에 같은 내용을 봅니다.": "購入ページではDESCRIPTION・SIZE GUIDE・DELIVERY GUIDEの欄に分かれて表示されます。3つの欄はすべて必須で、欄ごとに文章を書くか画像(サイズ表・配送案内の画像など)をアップロードしてください。インフルエンサーも販売申請前に同じ内容を確認します。",
