  "가격 · 옵션 · 배송비 · 판매기간 · 사이즈 가이드 · 배송 · 반품 안내는 위에 입력한 내용을 그대로 써요. 재고 수량은 고객에게 알려주지 않고 품절 여부만 안내해요.": "価格・オプション・送料・販売期間・サイズガイド・配送・返品のご案内は、上で入力した内容をそのまま使います。在庫数はお客様に伝えず、品切れかどうかだけを案内します。",
