  "협찬 상품을 받을 배송정보를 입력해 주세요. 업로드 일정은 픽스폴리오 담당자가 연락드려 조율해요.": "協賛商品を受け取る配送情報を入力してください。アップロード日程はPICKSfolioの担当者が連絡して調整します。",
  "배송지를 확인하고 협찬 상품을 보낸 뒤 송장번호를 입력해 주세요.": "配送先を確認し、協賛商品を送った後に送り状番号を入力してください。",
  "인플루언서가 배송정보를 입력하면 배송지가 여기에 나와요.": "インフルエンサーが配送情報を入力すると、配送先がここに表示されます。",
  "브랜드가 송장번호를 입력하면 전용 판매 링크가 열려요.": "ブランドが送り状番号を入力すると、専用の販売リンクが開きます。",
  "업로드 링크 · 파트너십 코드": "アップロードリンク · パートナーシップコード",
  "링크 업로드 완료 · 파트너십 코드 미입력": "リンクのアップロード完了 · パートナーシップコード未入力",
  "파트너십 코드를 입력해 주세요. 코드가 있어야 브랜드가 이 콘텐츠를 2차 광고로 돌릴 수 있어요.": "パートナーシップコードを入力してください。コードがあれば、ブランドがこのコンテンツを二次広告として配信できます。",
  "콘텐츠를 업로드한 뒤 콘텐츠 링크와 브랜디드 콘텐츠 파트너십 코드를 올려 주세요.": "コンテンツをアップロードした後、コンテンツのリンクとブランデッドコンテンツのパートナーシップコードを登録してください。",
  "인플루언서가 콘텐츠를 업로드하면 링크와 파트너십 코드가 여기에 나와요. 캠페인 이력에서 2차 광고로 돌릴 수 있어요.": "インフルエンサーがコンテンツをアップロードすると、リンクとパートナーシップコードがここに表示されます。キャンペーン履歴から二次広告として配信できます。",
  "인플루언서가 협업을 반려했어요. 이 협업은 진행되지 않아요.": "インフルエンサーがコラボを辞退しました。このコラボは進行しません。",
  "브랜드에 선정되었어요! 협찬 상품을 받을 배송정보를 입력하면 협업이 진행돼요.": "ブランドに選定されました!協賛商品を受け取る配送情報を入力すると、コラボが進行します。",
  "업로드 일정은 픽스폴리오 담당자가 연락드려 함께 조율해요.": "アップロード日程はPICKSfolioの担当者が連絡して一緒に調整します。",
  "배송정보 수정": "配送情報を修正",
