  "협찬 상품이 발송되면 콘텐츠 링크와 파트너십 코드를 올릴 수 있어요.": "協賛商品が発送されると、コンテンツのリンクとパートナーシップコードを登録できます。",
  "업로드한 콘텐츠 링크 (https://www.instagram.com/reel/...)": "アップロードしたコンテンツのリンク(https://www.instagram.com/reel/...)",
  "브랜디드 콘텐츠 파트너십 코드 (광고 코드)": "ブランデッドコンテンツのパートナーシップコード(広告コード)",
  "파트너십 코드를 올리면 브랜드가 이 콘텐츠를 2차 광고로 돌릴 수 있어요. 인스타그램 게시물 › 파트너십 광고 코드에서 복사해 주세요.": "パートナーシップコードを登録すると、ブランドがこのコンテンツを二次広告として配信できます。Instagramの投稿 › パートナーシップ広告コードからコピーしてください。",
  "콘텐츠 링크는 https:// 로 시작하는 주소로 입력해 주세요.": "コンテンツのリンクはhttps://で始まるURLで入力してください。",
