  "구매자가 문의하기를 누르면 이 주소로 이동해요. 자사몰 고객센터나 카카오톡 채널 주소를 넣어도 돼요.": "購入者が「問い合わせる」を押すと、このURLに移動します。自社サイトのカスタマーセンターやカカオトークチャネルのURLを入れても構いません。",
