  ")로 상품을 회수한 뒤 \"환불 처리\"를 눌러 주세요.": ")から商品を回収した後に「返金処理」を押してください。",
  "승인한 반품은 거절로 바꿀 수 없어요. 회수에 문제가 있으면 구매자에게 직접 연락하거나 픽스폴리오 고객센터로 문의해 주세요.": "承認した返品は拒否に変更できません。回収に問題がある場合は、購入者に直接連絡するか、PICKSfolioのカスタマーセンターにお問い合わせください。",
  "· 취소일": "· キャンセル日",
  "더 보기": "もっと見る",
  "주문 취소(전액 환불)": "注文をキャンセル(全額返金)",
  "송장을 입력하면 구매자는 주문취소 대신 반품을 요청할 수 있어요. '배송 완료'는 송장 입력 후 하루가 지나야 누를 수 있어요.": "送り状を入力すると、購入者は注文キャンセルの代わりに返品をリクエストできます。「配送完了」は送り状入力から1日経過後に押せます。",
  "승인하면 주문 배송지로 상품을 회수해 주세요. 회수 후 환불 처리를 눌러야 구매자에게 환불돼요.": "承認したら、注文の配送先から商品を回収してください。回収後に「返金処理」を押すと購入者に返金されます。",
  "승인한 뒤에는 거절로 바꿀 수 없어요.": "承認した後は拒否に変更できません。",
  "거절 사유 (선택, 적으면 구매자에게 보입니다)": "拒否理由(任意、入力すると購入者に表示されます)",
  "거절하면 반품 가능 기간과 구매확정 기준일이 거절 시점부터 다시 계산돼요.": "拒否すると、返品可能期間と購入確定の基準日が拒否した時点から再計算されます。",
  "취소 사유 선택": "キャンセル理由を選択",
  "재고 부족": "在庫不足",
  "배송 불가 지역": "配送不可地域",
  "구매자 요청": "購入者の依頼",
  "결제가 즉시 전액 취소되고 재고가 복구되며 인플루언서 수수료도 취소됩니다.": "決済がすぐに全額キャンセルされ、在庫が復元され、インフルエンサー手数料もキャンセルされます。",
  "반품 사유:": "返品理由:",
  "을 환불해요. 배송비는 환불되지 않고 카드 수수료(": "を返金します。送料は返金されず、カード手数料(",
  "%)를 뺀 금액이 정산돼요. 필요하면 구매자와 직접 협의해 주세요.": "%)を差し引いた金額が精算されます。必要であれば購入者と直接協議してください。",
  "환불 금액(상품 금액)": "返金金額(商品金額)",
  "인플루언서 수수료 · 이용료는 0원이 되고, 환불하지 않은 배송비에서 PG 수수료만 빼고 정산돼요.": "インフルエンサー手数料・利用料は0ウォンになり、返金しなかった送料からPG手数料のみを差し引いて精算されます。",
