  "진행 중인 어필리에이트예요. 상품을 누르면 지원 · 선정 인플루언서(한 화면) · 진행 단계(배송 현황) · 판매 현황을 볼 수 있어요. 선정하면 인플루언서가 배송정보를 입력하고, 협찬 상품을 보내 송장번호를 입력하면 전용 판매 링크가 열려요. 업로드 일정은 픽스폴리오 담당자가 양쪽과 조율해요.": "進行中のアフィリエイトです。商品を押すと、応募・選定インフルエンサー(1画面)・進行段階(配送状況)・販売状況を確認できます。選定するとインフルエンサーが配送情報を入力し、協賛商品を送って送り状番号を入力すると専用の販売リンクが開きます。アップロード日程はPICKSfolioの担当者が双方と調整します。",
