  "인플루언서에게 선정 알림이 가고, 인플루언서가 협찬 상품 배송정보를 입력하면 협업이 진행되고, 송장번호를 입력하면 인플루언서의 전용 판매 링크가 열립니다. 처음 선정하기 전에 아래 안내에 동의해 주세요.": "インフルエンサーに選定のお知らせが届き、インフルエンサーが協賛商品の配送情報を入力するとコラボが進行し、送り状番号を入力するとインフルエンサーの専用販売リンクが開きます。初めて選定する前に、下のご案内に同意してください。",
