  "자동 디엠 이용자 관리": "自動DM利用者の管理",
  "크리에이터 승인을 받은 새 인플루언서와 브랜드 매칭받기를 등록한 기존 인플루언서는 자동 디엠을 무료로 씁니다. 제안을 못 받은 사람은 계속 이용하고, 제안을 계속 거절하는 사람은 여기서 보고 중단할 수 있어요. 중단된 사람이 유가시딩 제안을 수락하면 자동으로 다시 열립니다.": "クリエイター承認を受けた新しいインフルエンサーと、ブランドマッチングに登録した既存のインフルエンサーは、自動DMを無料で使えます。提案を受けていない人は引き続き利用でき、提案を辞退し続ける人はここで確認して停止できます。停止された人が有償シーディングの提案を承諾すると、自動で再開されます。",
