  "만들어 둔 자동화는 지우지 않고 멈춰 둡니다. 아래 사유는 인플루언서의 자동 디엠 화면에 그대로 안내되며, 유가시딩 캠페인 제안을 수락하면 자동으로 다시 열립니다.": "作成した自動化は削除せずに停止しておきます。下の理由はインフルエンサーの自動DM画面にそのまま表示され、有償シーディングのキャンペーン提案を承諾すると自動で再開されます。",
